package com.nhpms.identity.entity;
import jakarta.persistence.*; import java.io.Serializable; import java.time.Instant; import java.util.UUID;
@Entity @Table(name="user_facility_access",schema="iam") @IdClass(UserFacilityAccess.Key.class)
public class UserFacilityAccess { @Id @Column(name="user_id") UUID userId; @Id @Column(name="facility_id") UUID facilityId; @Column(name="is_primary") boolean primaryAccess; @Column(name="assigned_at") Instant assignedAt=Instant.now(); public static class Key implements Serializable {UUID userId; UUID facilityId; public Key(){} public Key(UUID u,UUID f){userId=u;facilityId=f;} public boolean equals(Object o){return o instanceof Key k&&java.util.Objects.equals(userId,k.userId)&&java.util.Objects.equals(facilityId,k.facilityId);} public int hashCode(){return java.util.Objects.hash(userId,facilityId);} } public UserFacilityAccess(){} public UserFacilityAccess(UUID u,UUID f,boolean p){userId=u;facilityId=f;primaryAccess=p;} public UUID getUserId(){return userId;} public UUID getFacilityId(){return facilityId;} }
